"""Generated byte parts and sealed ZIP only; no selected executable is run."""
import hashlib
import io
import json
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch
import zipfile

ROOT=Path(__file__).resolve().parents[1]
sys.path[:0]=[str(ROOT/'app'),str(ROOT/'tools'),str(ROOT/'tests')]
import test_ai_runtime as fixture
from runtime_zip_parts import ZIPPartsReader,part_names
from runtime_archive import RuntimeArchive,inspect_archive,unpack_runtime


class ZIPPartsTests(unittest.TestCase):
    def setUp(self):
        temporary=tempfile.TemporaryDirectory();self.addCleanup(temporary.cleanup);self.base=Path(temporary.name)
        self.parts=self.base/'parts';self.parts.mkdir();self.names=['runtime.zip.part001','runtime.zip.part002']
        self.data=b'generated-first\x00second-part-data'
        for name,data in zip(self.names,(self.data[:12],self.data[12:])):(self.parts/name).write_bytes(data)

    def test_reader_seek_readinto_and_boundary_reads_match_one_file(self):
        with ZIPPartsReader(self.parts,self.names) as reader:
            reference=io.BytesIO(self.data)
            for position,whence,count in [(0,0,5),(8,0,12),(-8,2,8),(-5,1,3),(100,0,10),(0,0,-1)]:
                self.assertEqual(reader.seek(position,whence),reference.seek(position,whence))
                self.assertEqual(reader.read(count),reference.read(count));self.assertEqual(reader.tell(),reference.tell())
            reader.seek(9);buffer=bytearray(10);self.assertEqual(reader.readinto(buffer),10)
            self.assertEqual(bytes(buffer),self.data[9:19]);reader.validate()
        with self.assertRaises(ValueError):reader.read(1)

    def test_part_order_scope_and_count_are_strict(self):
        for names in ([],self.names[:1],self.names[::-1],[self.names[0]]*2,
                      [self.names[0],'other.zip.part002'],['../runtime.zip.part001',self.names[1]],self.names*5):
            with self.subTest(names=names),self.assertRaises(ValueError):part_names(names)

    def test_zero_oversize_missing_or_changed_part_is_rejected(self):
        first=self.parts/self.names[0]
        with patch('runtime_zip_parts.MAX_PART_BYTES',1),self.assertRaises(ValueError):ZIPPartsReader(self.parts,self.names)
        with ZIPPartsReader(self.parts,self.names) as reader:
            first.write_bytes(b'x'*12)
            with self.assertRaisesRegex(ValueError,'changed'):reader.validate()
        first.write_bytes(b'')
        with self.assertRaises(ValueError):ZIPPartsReader(self.parts,self.names)
        first.unlink()
        with self.assertRaises(ValueError):ZIPPartsReader(self.parts,self.names)

    def test_read_buffer_limit_does_not_advance_or_allocate_full_archive(self):
        with ZIPPartsReader(self.parts,self.names) as reader:
            with patch('runtime_zip_parts.MAX_READ',4),self.assertRaisesRegex(ValueError,'buffer limit'):reader.read()
            self.assertEqual(reader.tell(),0);self.assertEqual(reader.read(4),self.data[:4])

    def test_split_zip_inspection_and_expansion_preserve_binding_without_join_file(self):
        source=fixture.fixture(self.base/'source');memory=io.BytesIO()
        with zipfile.ZipFile(memory,'w',compression=zipfile.ZIP_DEFLATED) as archive:
            for path in source.rglob('*'):
                if path.is_file():archive.writestr(path.relative_to(source).as_posix(),path.read_bytes())
        raw=memory.getvalue();boundary=len(raw)//2
        for name,data in zip(self.names,(raw[:boundary],raw[boundary:])):(self.parts/name).write_bytes(data)
        before={p.name:p.read_bytes() for p in self.parts.iterdir()}
        with patch('subprocess.Popen',side_effect=AssertionError('No selected code execution')):
            spec=inspect_archive(self.parts,parts=self.names)
            self.assertEqual(spec.parts,tuple(self.names));self.assertEqual(RuntimeArchive.parse(spec.to_dict()),spec)
            info=unpack_runtime(self.parts,self.base/'expanded',spec)
        self.assertEqual(info['manifest_sha256'],hashlib.sha256((source/'aredoko-ai-runtime.json').read_bytes()).hexdigest())
        self.assertEqual(before,{p.name:p.read_bytes() for p in self.parts.iterdir()})
        self.assertEqual({p.relative_to(self.base).as_posix() for p in self.base.rglob('*.zip')},
                         {'source/python311.zip','expanded/python311.zip'})
        with self.assertRaisesRegex(ValueError,'overlaps'):unpack_runtime(self.parts,self.parts/'unsafe',spec)


if __name__=='__main__':unittest.main()
